def tbl(head, rows, widths):
 d=[[P(x,'TH') for x in head]]+[[P(x,'TC') for x in r] for r in rows]
 t=Table(d,colWidths=widths,repeatRows=1)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),navy),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#AAB8BE')),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F3F6F7')]),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)])); return t
class Flow(Flowable):
 def __init__(self, kind): super().__init__(); self.kind=kind; self.width=468; self.height=160
 def draw(self):
  c=self.canv; c.saveState(); c.setStrokeColor(teal); c.setFillColor(pale)
  def b(x,y,w,title,sub):
   c.roundRect(x,y,w,45,6,stroke=1,fill=1); c.setFillColor(navy); c.setFont('Times-Bold',8); c.drawCentredString(x+w/2,y+27,title); c.setFillColor(colors.darkgray); c.setFont('Times-Roman',6.8); c.drawCentredString(x+w/2,y+12,sub); c.setFillColor(pale)
  def a(x,y,u,v):
   c.line(x,y,u,v); c.line(u,v,u-5,v+3); c.line(u,v,u-5,v-3)
  if self.kind=='architecture':
   b(0,95,95,'Browser canvas','React / React Flow'); b(125,95,95,'Compiler','TypeScript graph → AST'); b(250,95,95,'Worker + WASM','Rust engine'); b(375,95,95,'FastAPI','AGT1 binary data')
   a(95,117,125,117); a(220,117,250,117); a(375,105,345,105); b(250,20,95,'Frozen files','daily OHLCV'); a(297,65,297,95)
  elif self.kind=='pipeline':
   labels=[('AGT1 file','OHLCV'),('Borrowed view','price columns'),('Indicators','SMA/EMA/RSI'),('Evaluator','signals'),('Simulator','orders/fills'),('Metrics','equity/risk')]
   for i,(t,sub) in enumerate(labels): b(i*78,80,70,t,sub)
   for i in range(5): a(i*78+70,102,(i+1)*78,102)
   b(160,15,145,'Compiler AST','ordered validated operations'); a(232,60,270,80)
  else:
   for x,t in [(20,'Browser'),(150,'API'),(280,'Worker'),(410,'WASM')]:
    c.setFillColor(pale); c.roundRect(x,122,55,24,4,stroke=1,fill=1); c.setFillColor(navy); c.setFont('Times-Bold',8); c.drawCentredString(x+27,131,t); c.setStrokeColor(colors.gray); c.setDash(2,3); c.line(x+27,20,x+27,122); c.setDash()
   for x,y,u,v in [(75,100,150,100),(150,78,75,78),(75,56,280,56),(280,34,410,34)]: a(x,y,u,v)
  c.restoreState()
def page(c,doc):
 c.saveState(); c.setStrokeColor(colors.HexColor('#CCD6DA')); c.line(1.5*inch,.72*inch,W-inch,.72*inch); c.setFont('Times-Roman',8); c.setFillColor(colors.gray); c.drawString(1.5*inch,.52*inch,'AlgoTrace | Minor Project Report | BIT Mesra Jaipur'); c.drawRightString(W-inch,.52*inch,str(doc.page)); c.restoreState()
doc=SimpleDocTemplate(str(OUT),pagesize=A4,leftMargin=1.5*inch,rightMargin=inch,topMargin=.88*inch,bottomMargin=1.15*inch,title='AlgoTrace: A Browser-Based Backtesting Platform for Indian Equities',author='Yash Raj and Navyansh Vyas')
z=Spacer(1,12); story=[]
# Cover and institutional front matter follow the supplied application-based format.
story += [Spacer(1,.5*inch),P('ALGOTRACE','Cover'),P('A Browser-Based Backtesting Platform for Indian Equities','Cover'),P('A Project Report','Sub'),P('Submitted in partial fulfilment of the requirements for the award of the Degree of','Ctr'),z,P('BACHELOR OF TECHNOLOGY','Cover'),P('IN','Ctr'),P('COMPUTER SCIENCE AND ENGINEERING','Cover'),z,P('BY','Ctr'),P('Yash Raj  (BTECH/25143/23)<br/>Navyansh Vyas  (BTECH/25172/23)','Cover'),P('Under the guidance of<br/><b>Dr. Abhishek Tiwari</b><br/>Assistant Professor','Ctr'),z,P('DEPARTMENT OF COMPUTER SCIENCE ENGINEERING','Ctr'),P('BIRLA INSTITUTE OF TECHNOLOGY, MESRA<br/>OFF-CAMPUS, JAIPUR<br/>MO-2026','Ctr'),P('23 November 2026','Ctr'),PageBreak(),P('APPROVAL OF THE GUIDE','Chap'),P('Recommended that the report entitled “AlgoTrace: A Browser-Based Backtesting Platform for Indian Equities” presented by Yash Raj (BTECH/25143/23) and Navyansh Vyas (BTECH/25172/23) under my supervision be considered for acceptance as part of the requirements for the Bachelor of Technology degree. This space is reserved for the guide’s review and approval.','BodyX'),z,z,P('Date: ____________________','BodyX'),z,P('________________________________________<br/>Dr. Abhishek Tiwari<br/>Assistant Professor<br/>Department of CSE<br/>BIT Mesra, Off-Campus Jaipur','Ctr'),PageBreak(),P('DECLARATION CERTIFICATE','Chap'),P('We, Yash Raj and Navyansh Vyas, declare that this report describes the AlgoTrace project work attributed to us. Before signing or submitting, we will verify that all factual statements are supported, cite outside material, and follow the Institute’s academic integrity requirements. The declaration statements below require confirmation by the students:','BodyX')]
for x in ['The submitted work is original and was completed by the students under the stated supervision.','The work has not been submitted to another institute for another degree or diploma.','Institute guidelines and the Ethical Code of Conduct have been followed.','External data, frameworks, and quoted material are acknowledged and cited.']: story.append(P('• '+x,'BodyX'))
story += [z,P('Date: 23/11/2026','BodyX'),z,P('______________________________                         ______________________________<br/>Yash Raj (BTECH/25143/23)                              Navyansh Vyas (BTECH/25172/23)','Ctr'),PageBreak(),P('CERTIFICATE OF APPROVAL','Chap'),P('This page follows the supplied format and is reserved for institutional certification after examination. No approval, examination result, or examiner signature is represented in this prepared report.','BodyX'),z,P('This is to certify that the work embodied in this report entitled “AlgoTrace: A Browser-Based Backtesting Platform for Indian Equities”, carried out by Yash Raj (BTECH/25143/23) and Navyansh Vyas (BTECH/25172/23), has been reviewed for the Bachelor of Technology degree, subject to the Institute examination and approval process.','BodyX'),z,P('Date: ____________________     Place: BIT Mesra, Off-Campus Jaipur','BodyX'),z,z,P('______________________________                         ______________________________<br/>Internal Examiner                                                       External Examiner','Ctr'),z,P('________________________________________<br/>(Chairman)<br/>Incharge, Department of CSE','Ctr'),PageBreak(),P('ABSTRACT','Chap'),P('AlgoTrace is an educational browser application for constructing and backtesting rule-based strategies on frozen daily Indian equity data. It addresses the reproducibility problem between a strategy idea and a reported result: editable graph structure must be validated, translated to a stable representation, executed without look-ahead, and evaluated under explicit cost and metric rules. The project combines a React/TypeScript interface, a standalone graph compiler, a pure Rust backtesting engine compiled to WebAssembly, and a local FastAPI service for frozen AGT1 prices. The compiler validates a strategy graph and emits a deterministic AST. The browser fetches price bytes, transfers them to a Web Worker, and the worker executes the engine in WASM. The implementation includes a node canvas, three strategy templates, compiler diagnostics, graph file operations, and a worker-backed SMA crossover demonstration. The frozen snapshot includes the NIFTY 50 index and fifteen stocks downloaded once through yfinance. It is unofficial, adjusted for corporate actions, and subject to survivorship bias. Verification includes hand-calculated Rust fixtures, property and no-look-ahead tests, compiler tests, real-WASM integration, API tests, vectorbt comparisons, and local Chromium flows. Eight of nine full-history vectorbt comparisons pass; the remaining SBIN stop-strategy overlap is a documented semantic exception. This report describes implemented work and known limitations; it does not claim brokerage execution, investment advice, public deployment, profitability, or institute approval.','BodyX'),P('<b>Keywords:</b> backtesting, algorithmic trading, WebAssembly, Rust, TypeScript compiler, NSE, reproducibility','BodyX'),PageBreak(),P('ACKNOWLEDGEMENT','Chap'),P('We would like to thank our guide, Dr. Abhishek Tiwari, Assistant Professor, for guidance on the project. We acknowledge the Department of Computer Science Engineering, BIT Mesra Off-Campus Jaipur, for the academic setting in which this work was undertaken. We will revise this text to reflect only assistance actually received.','BodyX'),P('We acknowledge the maintainers and communities behind Rust, React, TypeScript, FastAPI, WebAssembly, vectorbt, yfinance, React Flow, and Lightweight Charts. Their software is cited in the references.','BodyX'),z,P('Yash Raj and Navyansh Vyas<br/>23 November 2026','Ctr'),PageBreak(),P('CONTENTS','Chap')]
for x in ['ABSTRACT','ACKNOWLEDGEMENT','1. INTRODUCTION','2. SOFTWARE REQUIREMENTS (SRS PART)','3. SYSTEM DESIGN (SDS PART)','4. IMPLEMENTATION OF THE DESIGN','5. CONCLUSION AND FUTURE SCOPE','6. REFERENCES','7. PLAGIARISM REPORT']: story.append(P(x,'BodyX'))
story += [P('Chapter order follows the supplied application-based report format. Page numbers are printed in the footer.','SmallX'),PageBreak()]
# 1 Introduction
story += [P('1. INTRODUCTION','Chap'),P('1.1 Introduction','Sec'),P('Backtesting estimates how a strategy would have behaved on historical observations under stated assumptions. It is valuable for learning and comparison, but results depend on data quality, order timing, fees, and implementation details. A signal calculated from a closing price is not generally available before that close; filling it at the same close can introduce look-ahead. A reproducible workflow must expose these assumptions, reject invalid inputs, and preserve enough output to inspect trades and equity.','BodyX'),P('AlgoTrace is a local educational application for building a long-only strategy as a typed node graph, compiling that graph to an AST, and running it in a Rust engine through WebAssembly. Historical price files are served locally by FastAPI; strategy execution occurs in the browser worker. The intended users are students and researchers learning deterministic backtesting, not users seeking live execution.','BodyX'),P('1.2 Purpose and problem definition','Sec'),P('The project aims to make the path from strategy graph and daily data to orders, trades, equity, and metrics explicit and testable. The compiler must reject malformed or ill-typed graphs before execution; the engine must process bars in time order; whole-share and fee rules must be reproducible; and comparisons with other tools must report disagreements instead of concealing them.','BodyX'),P('1.3 Scope','Sec'),P('Implemented scope includes the graph canvas; the TypeScript compiler; a native pure Rust engine; WebAssembly bindings; one frozen set of daily market data; local FastAPI routes; a worker-backed SMA crossover page; three graph templates; and reference comparisons. The engine implements the catalog and AST described in the project specifications.','BodyX')]
for x in ['In scope: indicators and signal nodes, daily long-only simulation, next-bar open execution, charges, stop/target logic, metrics, and parameter sweeps.','Out of scope: live feeds, brokerage connectivity, order routing, public hosting, cloud accounts, user management, collaborative editing, and investment recommendations.','The frozen universe uses current large companies, so survivorship bias is present. yfinance is an unofficial educational source; corporate-action-adjusted prices differ from historical transaction prices.']: story.append(P('• '+x,'BodyX'))
story += [P('1.4 Users and technology stack','Sec'),tbl(['User','Use','Current access'],[['Student/researcher','Build and inspect a strategy and run the local example.','Browser canvas and WASM demo.'],['Guide/evaluator','Review design, evidence, tests and limitations.','Report, source, commands and local demo.'],['Guest','Observe demonstration.','Local browser only; no deployed public service.']],[105,190,145]),z,tbl(['Layer','Technology','Responsibility'],[['Frontend','React, TypeScript, Vite, React Flow, Zustand','Canvas and browser UI.'],['Compiler','TypeScript, Vitest, fast-check','Graph validation and AST lowering.'],['Engine','Rust, serde, wasm-bindgen','Indicators, evaluation, simulation, metrics.'],['Browser','Web Worker, WASM, Lightweight Charts','Off-main-thread execution and equity chart.'],['API/data','FastAPI, Uvicorn, AGT1, yfinance snapshot','Local price bytes and metadata.'],['Validation','vectorbt, pandas, pytest, proptest, Playwright','Reference and regression checks.']],[75,160,205]),PageBreak()]
# 2 SRS
story += [P('2. SOFTWARE REQUIREMENTS (SRS PART)','Chap'),P('2.1 Functional requirements','Sec')]
for x in ['FR-1 Authoring: palette supports every operation in the specification and bounded parameter editors.','FR-2 Connections: typed ports use Series, BoolSeries, or Number; illegal wiring is blocked using compiler-owned type rules.','FR-3 Diagnostics: compile on graph changes and show stable error codes, beginner-friendly messages, hints, and unreachable-node warnings.','FR-4 Graph operations: three templates, undo/redo, delete/duplicate, and JSON save/load in AI graph format.','FR-5 Data: local API exposes health, available symbols, and date-filtered AGT1 bytes with a bar-count header.','FR-6 Execution: client transfers bytes and AST to a worker; worker runs Rust/WASM and returns equity, trade columns, metrics, and timings.','FR-7 Simulation: apply next-bar fills, whole-share limits, per-fill costs, protective orders, end-of-data rules, and risk metrics.','FR-8 Research comparison: use shared signals, zero costs/slippage, explicit vectorbt settings, and named exceptions.']: story.append(P('• '+x,'BodyX'))
story += [P('2.2 Non-functional requirements','Sec')]
for x in ['Determinism: canonical AST serialization, stable ordering, and timestamp-free output.','Correctness: hand-worked examples, no-look-ahead checks, property tests, and explicit comparison tolerances.','Usability: labeled inputs, typed ports, bounded parameter fields, reusable templates, and actionable errors.','Reliability: reject invalid price files; maintain whole shares and non-negative cash.','Performance: move backtests to a worker and exchange larger arrays as typed buffers; no production latency claim is made.','Portability: local Node/pnpm, Rust/WebAssembly, and Python setup. Browser acceptance remains local-only.']: story.append(P('• '+x,'BodyX'))
story += [P('2.3 Constraints and assumptions','Sec')]
for x in ['Data is daily and frozen; it is not streaming or a complete historical constituent universe.','Adjusted OHLC and present-day company selection cause price-comparability and survivorship limitations.','Index/stock comparisons join on timestamp; they do not align by bar position.','No database, Redis, hosted deployment, authentication system, or production threat model is implemented.','The report records no independent user study or formal accessibility audit.']: story.append(P('• '+x,'BodyX'))
story += [PageBreak(),P('3. SYSTEM DESIGN (SDS PART)','Chap'),P('3.1 System architecture','Sec'),P('The application separates the canvas, compiler, backtesting runtime, and data service. The compiler accepts the AI graph format and emits the engine AST. The browser fetches bytes from FastAPI, transfers them to a module worker, and WASM reads the allocated data for execution. The API does not run a backtest.','BodyX'),Flow('architecture'),P('Figure 1. Logical architecture and data boundary.','Cap'),P('3.2 Module design','Sec'),tbl(['Module','Responsibility'],[['Canvas/store','React Flow components, Zustand graph, editing history, diagnostics, templates and files.'],['Compiler','Input validation, normalization, Kahn ordering/cycle detection, type/parameter checks, reachability, duplicate merging and AST lowering.'],['Engine data/evaluation','AGT1 borrowed view, indicators, ordered AST evaluation, boolean and numeric series.'],['Engine simulation','Orders, fills, costs, protective exits, equity and trade records.'],['Metrics/sweep','Return and risk measures, null undefined values, repeated parameter runs.'],['WASM wrapper/worker','Reserve/free data memory, execute JSON AST, read output pointers, transfer arrays.'],['API','Health, symbols and date filtered binary data; no cache.']],[120,340]),P('3.3 Data and schema design','Sec'),P('Each AGT1 file stores one symbol’s daily timestamps and OHLCV values in the project binary format. FastAPI returns application/octet-stream bytes and X-Bar-Count. Stock symbols are uppercase tickers suffixed with .NS, such as RELIANCE.NS; the index is ^NSEI. Loader checks reject NaN, non-positive prices, high below low, duplicate/non-increasing timestamps, while zero volume is allowed. Three shared zero-volume flat holiday bars were removed from each stock file using the documented 1e-9 relative flatness rule. Weekday gaps are reported, not filled with fabricated bars.','BodyX'),P('Graph JSON uses nodes with id, type and params plus edges with from, to and port. Canvas coordinates are excluded from the saved compiler graph. Compilation yields a deterministic versioned AST with config, ordered nodes and a strategy sink. Cost preset names resolve to bundled objects; caller-supplied rates and flat charges must be finite and non-negative.','BodyX'),P('3.4 User interface design','Sec'),P('The default screen is the strategy canvas. The palette is grouped into data, indicators, math, signals, and logic/strategy. Node editors expose inputs and allowed parameter ranges. Templates create SMA crossover, RSI oversold/overbought, and price-above-SMA with stop-loss graphs. Buttons support undo/redo, duplicate/delete, automatic layout, and graph JSON save/load. A broken-example gallery provides AT-E001–AT-E010 and AT-W001. The separate WASM demo shows the crossover equity curve and summary metrics.','BodyX'),P('3.5 Data-flow diagrams','Sec'),Flow('pipeline'),P('Figure 2. Backtest processing stages from the frozen binary file to metrics.','Cap'),Flow('transfer'),P('Figure 3. Browser/API/worker execution sequence.','Cap'),P('3.6 Sequence diagram','Sec'),P('The request/response order is: browser requests symbol bytes from FastAPI; API returns AGT1 bytes; page compiles graph and transfers bytes plus AST to the worker; worker initializes WASM, writes input bytes and calls the engine; the worker copies result columns into transferable buffers; page displays chart and summary. On first load, initialization is measured separately from the API download.','BodyX'),PageBreak()]
# 4 Implementation
story += [P('4. IMPLEMENTATION OF THE DESIGN','Chap'),P('4.1 Program architecture','Sec'),P('The Rust crate is organized into data/types, indicators, evaluator, costs, simulator, metrics, sweep, and WASM API modules. Native tests exercise the same core library used for WebAssembly. The compiler is a separate TypeScript workspace package. The canvas calls compiler-provided connection validation rather than duplicating allowed type rules. FastAPI reads local frozen files directly.','BodyX'),P('The browser fetches an ArrayBuffer and transfers ownership to the worker. The worker reserves WASM memory and writes input bytes once. The Rust engine then reads the resident data in place. The wrapper reacquires typed array views after calls that can grow WebAssembly memory. The worker transfers copied result buffers back to the page. “Zero-copy” is limited to repeated engine reads from stored input; the initial browser-to-WASM write is a copy.','BodyX'),P('4.2 Outline of code','Sec'),tbl(['Path','Role'],[['engine/src/data.rs','AGT1 reader and validated price view.'],['engine/src/indicators.rs','SMA, EMA and RSI warm-up semantics.'],['engine/src/evaluator.rs','AST node order, series evaluation, DELAY and crossover behavior.'],['engine/src/simulator.rs','Scheduled fills, stops/targets, costs and equity.'],['engine/src/metrics.rs; sweep.rs','Performance measures and parameter sweeps.'],['compiler/src/passes/','Separate compiler validation and lowering passes.'],['web/src/canvas/','Custom nodes, palette, Zustand state, files and compiler feedback.'],['web/src/engine/','WASM wrapper, worker protocol and integration checks.'],['api/app/; api/scripts/','FastAPI routes and frozen data utilities.']],[155,305]),P('4.3 Frontend/backend interaction','Sec'),P('The canvas validates strategy graphs continuously. The backtest demo compiles the checked-in SMA(10)/SMA(30) graph, fetches the full RELIANCE.NS history, sends bytes and AST to a Web Worker, and plots worker results. Users can switch from zero_costs to zerodha_equity_delivery. API failure, symbol errors, and compiler messages have visible UI paths. Local Playwright starts the API and Vite servers and uses real Chromium.','BodyX'),P('4.4 Performance and result analysis','Sec'),P('The reference tests compare SMA(10)/SMA(30), RSI(14) with 30/70 thresholds, and close above/below SMA(20) with a 10% stop. They use initial capital Rs 100,000, whole shares, long-only, no stacking, next-bar open fills, zero costs and zero slippage. Identical entry and exit signal arrays are supplied to both tools. Trades are compared on exact dates and share quantities; prices and equity use 1e-6 relative tolerance.','BodyX'),tbl(['Strategy','RELIANCE.NS','TCS.NS','SBIN.NS','Summary'],[['SMA crossover','Pass (79 records)','Pass (77)','Pass','Exact trade dates/shares; numeric tolerance passes.'],['RSI(14)','Pass (17)','Pass (16)','Pass','Exact trade dates/shares; numeric tolerance passes.'],['Close vs SMA + stop','Pass (236)','Pass (229)','Exception','SBIN is compared through bar 2501 only.']],[83,65,50,50,212]),P('Table 1. Full-history reference status; SBIN stop strategy has one named order-precedence exception.','Cap'),P('At SBIN.NS bar 2502 (2020-03-02), a signal exit was scheduled before the bar, and the open was below the stop. The engine applies G15: scheduled signal exits fill at open before intrabar stops. vectorbt built-in stop handling exits at the stop. Engine fill was Rs 281.8839, vectorbt fill Rs 262.9133; equity mismatch was approximately 6.73%. Eight of nine comparisons pass; for the ninth, checking stops at the divergent bar would conflate distinct semantics, so the accepted comparison ends at bar 2501. Engine behavior was not altered to force parity.','BodyX'),P('The frozen RELIANCE.NS SMA demo reports final equity Rs 291,218.03 and 78 closed trades. vectorbt lists 79 records because one position remains open at end of data. Metrics count only closed trades. These are reproducible outputs for this frozen snapshot and settings, not a forecast or profitability claim.','BodyX'),P('4.5 Verification evidence','Sec'),tbl(['Area','Evidence recorded'],[['Rust','35 integration tests including hand calculations, no-look-ahead and proptest; fmt and clippy clean per project notes.'],['Compiler','One fixture per AT-E001–E010, warning graph, golden ASTs, determinism and fast-check fuzz tests.'],['WASM','Real compiled binary integration; 20-bar expected final equity Rs 1,250, one closed trade, zero charges.'],['API/data','File roundtrip, quality and endpoint pytest coverage; 16 frozen AGT1 symbols.'],['Reference','Eight of nine full-history strategy/symbol comparisons pass at stated tolerances.'],['Browser','Local Chromium flow checks RELIANCE reference output and manually builds crossover, invalid connection refusal and every diagnostic example.']],[75,375]),P('The statements above summarize repository test records. They are not a new independent audit run while generating this document.','SmallX'),PageBreak()]
# 5-7
story += [P('5. CONCLUSION AND FUTURE SCOPE','Chap'),P('5.1 Conclusion','Sec'),P('AlgoTrace demonstrates an end-to-end educational pipeline from typed visual graph and frozen price data to deterministic AST execution in a Rust engine running in the browser. The design makes order timing, whole-share fills, costs, stops, end-of-data treatment, and undefined metrics explicit. It uses tests at several boundaries and reports a meaningful cross-engine stop-order mismatch rather than loosening the comparison tolerance.','BodyX'),P('The current result is a local prototype for learning and reproducible experiments on one frozen dataset. Unofficial and adjusted data, survivorship bias, limited universe, lack of live execution, and the one reference exception restrict conclusions. The application should not be treated as investment advice or a production trading service.','BodyX'),P('5.2 Future scope','Sec')]
for x in ['Add a known-limitations statement and expand provenance and calendar reconciliation.','Evaluate historical constituent universes and independently audited price sources.','Extend cross-engine tests with documented semantic adapters instead of changing accepted engine rules.','Add user-selectable symbol, date range, costs and capital only with corresponding validation and fixtures.','Conduct usability, accessibility and responsive-design studies and report measured outcomes.','Define security, resource, hosting and operational requirements before public deployment.','Evaluate any future AI strategy generation separately for invalid graph rates, transparency and safety.','Add multi-symbol portfolio analytics only with a specified timestamp-alignment model.']: story.append(P('• '+x,'BodyX'))
